INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('GEN-001', 'ALL', 'Line arithmetic', 'critical', 'Every invoice line', 'extended_amount = quantity × unit_price', 'Workday invoice line', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('GEN-002', 'ALL', 'Workday vs POMS value match', 'critical', 'Invoice references a POMS order', 'Order number exists in POMS and invoice subtotal (excl. VAT) equals POMS gross_taxable_amount. Skipped for prepayments, delivery notes and credit notes, and superseded by NO21-004 once an NGA tracker response exists', 'POMS order', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('GEN-003', 'ALL', 'VIN match', 'high', 'Invoice references a POMS order', 'Invoice VIN equals POMS VIN', 'POMS order', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`, `remediation`) VALUES ('SE21-001', 'SE21', 'Related party revenue category', 'high', 'Bill-To or Sold-To is a related-party financing bank (customer.related_party = true) AND line description contains ''Brand''', 'Line revenue_category = 3030', 'Workday customer master + invoice line', 'FAIL', 'Manually correct the revenue category to 3030.');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('NO21-001', 'NO21', 'NGA tracker captured', 'high', 'Bill-To customer.nga_customer = true', 'A tracker row exists for the invoice with invoice_number, customer_id, model_number, total_invoice_price, gross_taxable_amount and base_price populated', 'NGA tracker', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('NO21-002', 'NO21', 'NGA response received', 'high', 'NGA customer with a tracker row', 'tracker.response_status = RESPONDED', 'NGA tracker', 'HOLD');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('NO21-003', 'NO21', 'Fee lines removed when instructed', 'critical', 'tracker.remove_fees = true', 'No line whose revenue category is a fee category (3041, 3042, 3043)', 'NGA tracker + revenue category master', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('NO21-004', 'NO21', 'Revised gross and base applied', 'critical', 'NGA tracker responded', 'Invoice taxable amount = revised_gross_amount; vehicle line unit price = revised_base_price', 'NGA tracker', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('NO21-005', 'NO21', 'VAT recalculated after amendment', 'critical', 'Every NO21 invoice', 'tax_amount = taxable_amount × 25%', 'Workday tax', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('NO21-007', 'NO21', 'Factoring payment captured', 'medium', 'A payment is applied to the invoice as ON_ACCOUNT', 'payment_id exists in the factoring tracker', 'Factoring tracker', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('PT21-001', 'PT21', 'Leasing licence plate', 'high', 'Bill-To is a leasing company that requires the licence plate (customer.leasing_plate_required = true)', 'Vehicle line description contains the POMS license_plate', 'POMS order', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('PT21-002', 'PT21', 'Personal loan bill-to', 'high', 'POMS financing_type = PERSONAL_LOAN and the partner is not flagged bank_sold_to_exception', 'Bill-To = Sold-To = buyer', 'POMS order', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('PT21-003', 'PT21', 'Bank sold-to exception', 'high', 'POMS financing partner is flagged bank_sold_to_exception', 'Bill-To = Sold-To = the loan provider', 'POMS order', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('PT21-004', 'PT21', 'VAT number on extras / prepayment', 'medium', 'document_kind is Sales Invoice Extra or prepayment', 'customer_vat_number populated (fallback source: Salesforce)', 'Workday + Salesforce', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('PT21-005', 'PT21', 'E&Y final invoice match', 'critical', 'An E&Y final invoice exists for the Workday invoice', 'invoice_date, customer name, PO number, VIN, amount excl. VAT and total all equal', 'E&Y final invoices', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('PT21-006', 'PT21', 'Gapless numbering and approval order', 'critical', 'Statutory invoice types PRT Invoice / Credit note - EY', 'Workday statutory number equals the E&Y number; an APPROVED invoice must have an E&Y final invoice', 'E&Y final invoices', 'FAIL');
INSERT INTO validation_rule (`rule_id`, `company`, `name`, `severity`, `condition`, `check`, `source`, `outcome_on_fail`) VALUES ('PT21-007', 'PT21', 'Exclude internal zero-value documents', 'info', 'Delivery Note or Sales Invoice Extra with zero value', 'Flag as excluded from the daily E&Y report', 'Workday', 'INFO');
